#!/usr/bin/env bash
# Generated by Phase: IMPLEMENT | Feature: EVOL-048
# ============================================================================
# check-plan-approval.sh — PreToolUse hook (Edit|Write|Bash): one planning stage, never zero.
# A write to a governed path on a branch class with no framework planning phase needs an approved plan.
# ONE definition: python3 scripts/gate.py plan --path <file> (config/quality.json → planning). exit 1 = blocked.
# Exit 2 + message on stderr = the Claude Code blocking contract. Fail-closed: a missing python3 or reader, or a
# payload that cannot be read, blocks with the resolution named. A well-formed payload without a file path passes.
# EVOL-065: the targets come from gate.py write-target — Edit/Write file_path and the shell's recognised writers.
# ============================================================================
cd "${CLAUDE_PROJECT_DIR:-$(git rev-parse --show-toplevel 2>/dev/null || pwd)}" || exit 2
PAYLOAD=$(cat)
# EVOL-065: a shell write meets the same gate. Reader fault on a Bash call → let through with a notice (the shell
# is the repair route; the git pre-commit hook stands behind it). Edit/Write stays fail-closed.
is_bash() { [[ "$PAYLOAD" =~ \"tool_name\"[[:space:]]*:[[:space:]]*\"Bash\" ]]; }
shell_passes() {  # the PreToolUse envelope: the only channel an exit-0 hook has to the model (EVOL-043)
  printf '{"hookSpecificOutput":{"hookEventName":"PreToolUse","additionalContext":"notice: the planning gate could not judge this shell command (%s) — let through: the shell is the repair route (git checkout origin/main -- scripts/gates, or bash scripts/factory-sync.sh)."}}\n' "$1"
  exit 0
}
if ! command -v python3 >/dev/null 2>&1; then
  is_bash && shell_passes "python3 is not on PATH"
  echo "BLOCKED: python3 is not on PATH — the planning gate cannot run. Install python3, then retry." >&2; exit 2
fi
if [ ! -f scripts/gate.py ]; then
  is_bash && shell_passes "scripts/gate.py is not delivered"
  echo "BLOCKED: the governance reader (scripts/gate.py) is not delivered — the write cannot be judged against the planning gate. Resolution: bash scripts/factory-sync.sh, then retry." >&2; exit 2
fi
# ONE reader names the targets (gate.py write-target): 4 nothing to judge · 1 guarded / unresolved · 0 the in-project targets.
WT=$(printf '%s' "$PAYLOAD" | python3 scripts/gate.py write-target --hook-json 2>&1); WT_RC=$?
case "$WT_RC" in
  0) ;;
  4) exit 0 ;;   # nothing to judge — 3 is gate.py's import guard (package broken): a fault, below
  1) printf '%s\n' "$WT" >&2; exit 2 ;;
  *)
    is_bash && shell_passes "gate.py write-target exit $WT_RC"
    case "$WT" in
      *"could not be read"*) echo "BLOCKED: the hook payload could not be read — the write cannot be judged against the planning gate. Retry the edit." >&2 ;;
      *) { echo "BLOCKED: the write could not be judged (gate.py write-target exit $WT_RC): $(printf '%s' "$WT" | head -c 300)"; echo "Resolution: repair scripts/gates/ from the shell — git checkout origin/main -- scripts/gates, or bash scripts/factory-sync.sh — then retry."; } >&2 ;;
    esac
    exit 2 ;;
esac
while IFS= read -r FILE; do
  [ -n "$FILE" ] || continue
  OUT=$(python3 scripts/gate.py plan --path "$FILE" 2>&1); RC=$?
  case "$RC" in
    0) ;;
    1) { echo "BLOCKED: no approved plan covers this write to '$FILE'."; echo "$OUT"; } >&2; exit 2 ;;
    *) { echo "BLOCKED: the planning gate could not judge the write to '$FILE' (gate.py plan exit $RC):"; echo "$OUT"; echo "Resolution: see the reason above; repair it from the shell (git checkout origin/main -- scripts/gates, or bash scripts/factory-sync.sh — neither is a recognised writer), then retry."; } >&2; exit 2 ;;
  esac
done <<< "$WT"
exit 0
